
const WORDS=[{"id": 0, "w": "迫不及待", "p": "pòbù jídài", "t": "成语", "m": "nóng lòng, không thể chờ đợi được", "coll": "迫不及待地打开、迫不及待地想知道", "s": "收到录取通知书后，她迫不及待地把这个好消息告诉了家人。"}, {"id": 1, "w": "依靠", "p": "yīkào", "t": "动词", "m": "dựa vào, phụ thuộc vào", "coll": "依靠自己、依靠经验", "s": "学习外语不能只依靠记忆，还需要不断练习和实际运用。"}, {"id": 2, "w": "借助", "p": "jièzhù", "t": "动词", "m": "nhờ vào, nhờ sự giúp đỡ của", "coll": "借助工具、借助网络", "s": "借助网络资源，我们可以接触到更加丰富的语言材料。"}, {"id": 3, "w": "勉强", "p": "miǎnqiǎng", "t": "形容词／副词", "m": "gắng gượng, cố gượng", "coll": "勉强答应、勉强完成", "s": "虽然身体还没恢复，他还是勉强完成了当天的工作。"}, {"id": 4, "w": "机构", "p": "jīgòu", "t": "名词", "m": "đơn vị, cơ quan, tổ chức", "coll": "教育机构、研究机构", "s": "这家研究机构长期关注不同年龄学习者的语言发展。"}, {"id": 5, "w": "栋", "p": "dòng", "t": "量词", "m": "tòa (nhà)", "coll": "一栋楼、两栋房子", "s": "学校新建了一栋教学楼，为学生提供了更好的学习环境。"}, {"id": 6, "w": "兴致勃勃", "p": "xìngzhì bóbó", "t": "成语", "m": "vô cùng hào hứng", "coll": "兴致勃勃地讨论、兴致勃勃地参观", "s": "学生们兴致勃勃地讨论着第一次出国交流的经历。"}, {"id": 7, "w": "专程", "p": "zhuānchéng", "t": "副词", "m": "đặc biệt đi", "coll": "专程拜访、专程赶来", "s": "为了向老师请教，他专程赶到学校，当面表达了自己的困惑。"}, {"id": 8, "w": "修养", "p": "xiūyǎng", "t": "名词", "m": "sự tu dưỡng; trình độ văn hóa, cách ứng xử", "coll": "个人修养、提高修养", "s": "真正的修养往往体现在如何对待与自己意见不同的人。"}, {"id": 9, "w": "接连", "p": "jiēlián", "t": "副词", "m": "liên tiếp, liên tục", "coll": "接连发生、接连几天", "s": "接连几天的降雨影响了交通，不少人不得不调整出行计划。"}, {"id": 10, "w": "涉及", "p": "shèjí", "t": "动词", "m": "liên quan đến, đề cập đến", "coll": "涉及隐私、涉及多个方面", "s": "这次讨论涉及学习方法、文化差异以及交流中的礼貌问题。"}, {"id": 11, "w": "隐私", "p": "yǐnsī", "t": "名词", "m": "sự riêng tư, đời tư", "coll": "保护隐私、个人隐私", "s": "未经允许，我们不应该公开他人的隐私。"}, {"id": 12, "w": "反感", "p": "fǎngǎn", "t": "形容词", "m": "có ác cảm, bực mình", "coll": "引起反感、感到反感", "s": "这种居高临下的口气容易引起听者的反感，不利于沟通。"}, {"id": 13, "w": "火药", "p": "huǒyào", "t": "名词", "m": "thuốc nổ", "coll": "火药味、火药的用途", "s": "讨论越来越激烈，双方的语气中渐渐有了火药味。"}, {"id": 14, "w": "忍耐", "p": "rěnnài", "t": "动词", "m": "nhẫn nại, kiềm chế", "coll": "忍耐一时、学会忍耐", "s": "面对暂时的困难，他学会了忍耐，也没有放弃自己的目标。"}, {"id": 15, "w": "着想", "p": "zhuóxiǎng", "t": "动词", "m": "nghĩ cho, lo cho", "coll": "为别人着想、替家人着想", "s": "作出决定之前，我们也应该为别人着想。"}, {"id": 16, "w": "策划", "p": "cèhuà", "t": "动词", "m": "đặt kế hoạch, chuẩn bị, trù tính", "coll": "策划活动、精心策划", "s": "几位老师共同策划了一场中外学生交流活动。"}, {"id": 17, "w": "达成", "p": "dáchéng", "t": "动词", "m": "đạt được", "coll": "达成共识、达成协议", "s": "经过多次讨论，双方终于就合作方式达成了共识。"}, {"id": 18, "w": "口气", "p": "kǒuqì", "t": "名词", "m": "giọng điệu", "coll": "商量的口气、严肃的口气", "s": "她用商量的口气提出建议，让对方更容易接受。"}, {"id": 19, "w": "缓和", "p": "huǎnhé", "t": "形容词／动词", "m": "dịu đi", "coll": "缓和气氛、关系缓和", "s": "一句真诚的道歉让原本紧张的气氛逐渐缓和下来。"}, {"id": 20, "w": "随意", "p": "suíyì", "t": "形容词", "m": "tùy ý", "coll": "随意更改、不能随意", "s": "已经确认的安排不能随意更改，否则会影响其他人的计划。"}, {"id": 21, "w": "而已", "p": "éryǐ", "t": "成语", "m": "trợ. mà thôi", "coll": "仅此而已、只是建议而已", "s": "这只是我个人的看法而已，大家可以继续提出不同意见。"}, {"id": 22, "w": "设置", "p": "shèzhì", "t": "动词", "m": "thiết lập", "coll": "设置目标、设置提醒", "s": "为了养成学习习惯，她在手机上设置了每天的提醒。"}, {"id": 23, "w": "动力", "p": "dònglì", "t": "名词", "m": "động lực", "coll": "学习动力、提供动力", "s": "清晰的目标能够为长期学习提供动力。"}, {"id": 24, "w": "固然", "p": "gùrán", "t": "连词", "m": "tất nhiên, dĩ nhiên, tuy", "coll": "固然重要、固然如此", "s": "兴趣固然重要，但要取得进步，仍然需要持之以恒的努力。"}, {"id": 25, "w": "恳切", "p": "kěnqiè", "t": "形容词", "m": "tha thiết, ân cần", "coll": "态度恳切、言辞恳切", "s": "他态度恳切地向老师请教，希望得到具体的建议。"}, {"id": 26, "w": "无非", "p": "wúfēi", "t": "副词", "m": "chẳng qua, chỉ", "coll": "无非是、无非为了", "s": "她每天坚持练习，无非是想让自己说得更自然一些。"}, {"id": 27, "w": "知音", "p": "zhīyīn", "t": "名词", "m": "bạn tri âm", "coll": "遇到知音、难得的知音", "s": "能遇到一位真正理解自己作品的知音，是许多创作者的愿望。"}, {"id": 28, "w": "客户", "p": "kèhù", "t": "名词", "m": "khách hàng", "coll": "联系客户、客户需求", "s": "在提出方案之前，我们应该先了解客户的实际需求。"}, {"id": 29, "w": "持久", "p": "chíjiǔ", "t": "形容词", "m": "lâu dài, bền vững", "coll": "持久的兴趣、效果持久", "s": "只有把兴趣转化为日常习惯，学习动力才可能更加持久。"}, {"id": 30, "w": "崩溃", "p": "bēngkuì", "t": "动词", "m": "sụp đổ, suy sụp", "coll": "情绪崩溃、系统崩溃", "s": "连续几天没有休息好，他感到情绪几乎要崩溃，于是决定暂时停下工作。"}, {"id": 31, "w": "果断", "p": "guǒduàn", "t": "形容词", "m": "quả quyết, kiên quyết", "coll": "果断决定、采取果断措施", "s": "了解情况后，负责人果断作出决定，立即调整原来的方案。"}, {"id": 32, "w": "斩钉截铁", "p": "zhǎndīng jiétiě", "t": "成语", "m": "như đinh đóng cột, cương quyết", "coll": "斩钉截铁地说、态度斩钉截铁", "s": "面对大家的疑问，她斩钉截铁地说：“我一定会坚持下去。”"}, {"id": 33, "w": "思维", "p": "sīwéi", "t": "名词", "m": "ý nghĩ, tư duy, tư tưởng", "coll": "思维方式、培养思维", "s": "学习一门外语不仅能帮助我们交流，也能让我们接触不同的思维方式。"}, {"id": 34, "w": "搭", "p": "dā", "t": "动词", "m": "ăn khớp, phù hợp", "coll": "很搭、不太搭", "s": "这件外套和那条裤子很搭，整体看起来十分协调。"}, {"id": 35, "w": "执行", "p": "zhíxíng", "t": "动词", "m": "chấp hành, tiến hành, thực hiện", "coll": "执行计划、执行任务", "s": "再完善的计划，如果不能认真执行，也很难取得预期的效果。"}, {"id": 36, "w": "啥", "p": "shá", "t": "代词", "m": "cái gì, nào", "coll": "有啥问题、说点啥", "s": "你有啥不明白的，就直接问，我们可以一起讨论。"}, {"id": 37, "w": "薪水", "p": "xīnshui", "t": "名词", "m": "tiền lương", "coll": "领取薪水、每月的薪水", "s": "他把每月薪水的一部分存了起来，准备继续进修。"}, {"id": 38, "w": "弊端", "p": "bìduān", "t": "名词", "m": "nhược điểm, mặt hạn chế", "coll": "存在弊端、克服弊端", "s": "这种做法虽然能节省时间，但也存在一些不容忽视的弊端。"}, {"id": 39, "w": "拼命", "p": "pīnmìng", "t": "副词", "m": "dốc sức, ra sức", "coll": "拼命练习、拼命工作", "s": "考试前才拼命复习，往往不如平时坚持积累有效。"}, {"id": 40, "w": "搁", "p": "gē", "t": "动词", "m": "đặt, gác lại", "coll": "搁在一边、暂时搁下", "s": "遇到暂时无法解决的问题，不妨先搁在一边，换个角度再想。"}, {"id": 41, "w": "颠倒", "p": "diāndǎo", "t": "动词", "m": "đảo ngược, lộn ngược", "coll": "颠倒顺序、昼夜颠倒", "s": "整理材料时，他不小心颠倒了两份文件的顺序。"}, {"id": 42, "w": "权衡", "p": "quánhéng", "t": "动词", "m": "cân nhắc, so đo, suy tính", "coll": "权衡利弊、反复权衡", "s": "选择学习方式之前，应该根据自己的情况权衡利弊。"}, {"id": 43, "w": "津津有味", "p": "jīnjīn yǒuwèi", "t": "成语", "m": "thích thú, say mê", "coll": "读得津津有味、听得津津有味", "s": "他把这本介绍语言文化的书读得津津有味，连时间都忘了。"}];
